/*
 * Load the two vendored typefaces (assets/fonts, SIL OFL) with the FontFace API.
 *  - desktop / userscript: base64 woff2 embedded in the payload, loaded from an
 *    ArrayBuffer: no network request, unaffected by the page's CSP;
 *  - extension: the woff2 files are web accessible resources of the extension.
 * __BD_FONTS__ is generated by scripts/build.mjs. If anything fails, the fallback
 * stacks in 00-tokens.css (Segoe UI Variable, system-ui) take over.
 */
BD.feature({
  id: "fonts",
  setup() {
    if (typeof __BD_FONTS__ === "undefined" || !document.fonts || typeof FontFace !== "function") return;
    const runtime = globalThis.chrome?.runtime || globalThis.browser?.runtime;
    const decode = (b64) => {
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return bytes.buffer;
    };
    for (const f of __BD_FONTS__) {
      try {
        let source;
        if (f.data) source = decode(f.data);
        else if (runtime?.getURL) source = `url("${runtime.getURL(`fonts/${f.file}`)}") format("woff2")`;
        else continue;
        const face = new FontFace(f.family, source, { weight: f.weight, unicodeRange: f.range, display: "swap" });
        document.fonts.add(face);
        face.load().catch((err) => BD.warn(`font ${f.file} failed:`, err));
      } catch (err) {
        BD.warn(`font ${f.file} failed:`, err);
      }
    }
  }
});
